 long initialTimerMs(){return timerMode.equals("Countdown")?countdownMinutes*60000L:timerMode.equals("Pomodoro")?25*60000L:0L;}
 String formatTime(long ms){long sec=Math.max(0,ms)/1000;return sec>=3600?String.format(java.util.Locale.US,"%02d:%02d:%02d",sec/3600,(sec/60)%60,sec%60):String.format(java.util.Locale.US,"%02d:%02d",sec/60,sec%60);}
 void startFocus(){if(running)return;if(!focusBreak && !timerMode.equals("Stopwatch") && remainingMs<=0)return;running=true;timerStartedAt=SystemClock.elapsedRealtime();focusTimer=new CountDownTimer(timerMode.equals("Stopwatch")?24L*60*60*1000:Math.max(1,remainingMs),250){public void onTick(long unused){updateTimerDisplay();}public void onFinish(){pauseFocus();if(focusBreak){focusBreak=false;remainingMs=25*60000L;show(6);new AlertDialog.Builder(MainActivity.this).setMessage("Break complete. Ready for the next Pomodoro?").setPositiveButton("OK",null).show();}else if(timerMode.equals("Pomodoro")){focusBreak=true;remainingMs=5*60000L;show(6);new AlertDialog.Builder(MainActivity.this).setMessage("25-minute study block finished. You can save the session or start the five-minute break.").setPositiveButton("OK",null).show();}else if(timerMode.equals("Countdown")){show(6);new AlertDialog.Builder(MainActivity.this).setMessage("Countdown finished. Tap Finish to save your eligible study time.").setPositiveButton("OK",null).show();}}}.start();}
 void updateTimerDisplay(){if(!running)return;long delta=Math.max(0,SystemClock.elapsedRealtime()-timerStartedAt);long displayed;if(focusBreak){displayed=Math.max(0,remainingMs-delta);}else if(timerMode.equals("Stopwatch")){displayed=studyElapsedMs+delta;}else{displayed=Math.max(0,remainingMs-delta);}if(page==6&&timerLabel!=null)timerLabel.setText((focusBreak?"Break: ":"")+formatTime(displayed));if(page==6&&focusFinishButton!=null)focusFinishButton.setEnabled((studyElapsedMs+(focusBreak?0:delta))>=600000L);}
 void pauseFocus(){if(!running)return;long delta=Math.max(0,SystemClock.elapsedRealtime()-timerStartedAt);if(focusBreak)remainingMs=Math.max(0,remainingMs-delta);else{long credited=timerMode.equals("Stopwatch")?delta:Math.min(delta,remainingMs);studyElapsedMs+=credited;if(!timerMode.equals("Stopwatch"))remainingMs=Math.max(0,remainingMs-delta);}if(focusTimer!=null){focusTimer.cancel();focusTimer=null;}running=false;}
 void resetFocus(){pauseFocus();studyElapsedMs=0;focusBreak=false;remainingMs=initialTimerMs();show(6);}
 @Override protected void onPause(){{boolean wasRunning=running;pauseFocus();if(wasRunning&&page==6&&timerLabel!=null){timerLabel.setText(focusBreak?"Break: "+formatTime(remainingMs):timerMode.equals("Stopwatch")?formatTime(studyElapsedMs):formatTime(remainingMs));if(focusFinishButton!=null)focusFinishButton.setEnabled(studyElapsedMs>=600000L);}}super.onPause();}
 @Override protected void onStop(){pauseFocus();super.onStop();}
